class _BodyLimit:
    """Reject oversized bodies before FastAPI parses them (pre-auth)."""
    def __init__(self, app, max_bytes: int, upload_max_bytes: int):
        self.app, self.max_bytes, self.upload_max_bytes = app, max_bytes, upload_max_bytes

    async def __call__(self, scope, receive, send):
        if scope["type"] != "http":
            return await self.app(scope, receive, send)
        headers = dict(scope["headers"])
        try:
            declared = int(headers.get(b"content-length") or 0)
        except ValueError:
            declared = 0
        cap = self.upload_max_bytes if scope["path"].endswith("/files") else self.max_bytes
        if declared > cap:
            return await Response("요청 본문이 너무 큼", status_code=413)(scope, receive, send)
        sent = 0

        async def limited():
            nonlocal sent
            message = await receive()
            sent += len(message.get("body", b""))
            if sent > cap:
                raise ClientDisconnect()
            return message

        return await self.app(scope, limited, send)

app.add_middleware(_BodyLimit, max_bytes=64 * 1024,
                   upload_max_bytes=settings.max_upload_bytes + 4096)

def extract_novnc(self, dest: Path) -> bool:
    marker = dest / "core" / "rfb.js"
    if marker.exists():
        return True
    with self._novnc_lock:            # one extraction per process
        if marker.exists():           # a waiter re-checks after the winner finished
            return True
        try:
            c = self.client.containers.create(self.settings.desktop_image, ["true"], network_mode="none")
        except (ImageNotFound, APIError):
            return False
        try:
            stream, _ = c.get_archive("/usr/share/novnc")
            out = b"".join(stream)
        except (NotFound, APIError):
            return False
        finally:
            c.remove(force=True)
        dest.parent.mkdir(parents=True, exist_ok=True)
        try:
            with tarfile.open(fileobj=io.BytesIO(out)) as tf:
                members = [m for m in tf.getmembers() if m.isfile() or m.isdir()]
                tf.extractall(dest.parent, members=members, filter="data")
        except (OSError, tarfile.TarError):
            shutil.rmtree(dest, ignore_errors=True)   # never serve a half tree
            return False
        return marker.exists()

@app.post("/login", include_in_schema=False)
def login(request: Request, token: str = Form(...)):
    if not same_origin(request.headers):
        raise HTTPException(403, "다른 출처의 요청")
    if not token.isascii() or not secrets.compare_digest(token.strip(), human_token):
        # 5마다 1건만 기록 + 주소별 초당 상한 (전체 상한은 _login_failures 쪽)
        if _login_failures.allow(request.client.host if request.client else "unknown"):
            try:
                box.log_human("ui_login_failed", None, {})
            except ServiceError:
                pass
        return render(request, "login.html", error="사람 토큰이 아님 (에이전트 토큰으로는 들어갈 수 없습니다)")
    return start_session(request, "/ui", "token")
